@pytest.mark.parametrize('boundary', ['browser_transcode', 'result_build', 'after_publication']) def test_same_job_restart_skips_sealed_inference_and_publishes_only_after_revalidation( publication_job, monkeypatch, boundary): from src.api.result_document import ResultDocument fixture = publication_job native_checkpoint_fixture(fixture, monkeypatch) execute, build, finish = worker.execute, worker.build_result, fixture.store.finish if boundary == 'browser_transcode': def interrupted(args, **kwargs): if '-crf' in args and args[args.index('-crf') + 1] == '20': raise KeyboardInterrupt('Simulated worker loss after sealed inference') return execute(args, **kwargs) monkeypatch.setattr(worker, 'execute', interrupted) elif boundary == 'result_build': def interrupted(*args, **kwargs): raise KeyboardInterrupt('Simulated worker loss during result build') monkeypatch.setattr(worker, 'build_result', interrupted) else: def interrupted(*args, **kwargs): assert (fixture.output / '.result/current.store').is_file() raise KeyboardInterrupt('Simulated worker loss after result publication') monkeypatch.setattr(fixture.store, 'finish', interrupted) with pytest.raises(KeyboardInterrupt, match='Simulated worker loss'): worker.process_job(fixture.store, fixture.job, fixture.settings) checkpoint = fixture.output / '.pipeline_checkpoint.json' sealed = checkpoint.read_bytes() before = {name: (fixture.output / name).read_bytes() for name in worker.REQUIRED_PIPELINE_FILES} assert fixture.store.get(fixture.job['id'])['status'] == 'PROCESSING' base = f'/api/analyses/{fixture.job["id"]}' assert fixture.client.get(base + '/result').status_code == 409 assert fixture.client.get(base + '/media/annotated').status_code == 404 monkeypatch.setattr(worker, 'execute', execute) monkeypatch.setattr(worker, 'build_result', build) monkeypatch.setattr(fixture.store, 'finish', finish) restarted = JobStore(fixture.settings.root) restarted.recover_interrupted(lambda job: worker.recoverable_completed_job(restarted, job)) resumed = restarted.claim() assert resumed['id'] == fixture.job['id'] and resumed['attempt'] == 2 worker.process_job(restarted, resumed, fixture.settings) assert restarted.get(resumed['id'])['status'] == 'COMPLETED' assert fixture.processing_calls.count('pipeline_stub') == 1 assert sum(isinstance(call, list) and '-stats_enc_pre' in call for call in fixture.processing_calls) == 1 assert checkpoint.read_bytes() == sealed assert {name: (fixture.output / name).read_bytes() for name in before} == before > assert fixture.client.get(base + '/result').json() == fixture.result E AssertionError: assert {'analysisGen...pty': [], ...} == {'contractVer...e': None, ...} E E Omitting 7 identical items, use -vv to show E Left contains 1 more item: E {'analysisGeneration': 'a90d9925d4fd1b6a6234f4d3783b6eac6dee51023c476c00283c23fa59783d84'} E Use -v to get more diff
